trial.program_source:
def transform(grid):
    a=[r[:] for r in grid]
    h=len(a); w=len(a[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=6: continue
            a[r][c]=0
            for y in range(r-1,-1,-1):
                if a[y][c]==3:
                    l=c; u=c
                    while l>0 and a[y][l-1]==3: l-=1
                    while u+1<w and a[y][u+1]==3: u+=1
                    for x in range(l,u+1): a[y][x]=0
                    break
    return a

